B.amb=new A.t("\u0414\u043e \u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f","\u041f\u0442\u0438\u0446\u044b \u0430\u0431\u0430\u0431\u0438\u043b\u044c","\u0421\u043b\u043e\u043d \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u043b\u0441\u044f \u0438 \u043e\u0442\u043a\u0430\u0437\u0430\u043b\u0441\u044f \u0438\u0434\u0442\u0438 \u043a \u041a\u0430\u0430\u0431\u0435. \u0410\u043b\u043b\u0430\u0445 \u043f\u043e\u0441\u043b\u0430\u043b \u0441\u0442\u0430\u0438 \u043f\u0442\u0438\u0446, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u0431\u0440\u043e\u0441\u0430\u043b\u0438 \u0432 \u0432\u043e\u0439\u0441\u043a\u043e \u043a\u0430\u043c\u043d\u0438 \u0438\u0437 \u043e\u0431\u043e\u0436\u0436\u0451\u043d\u043d\u043e\u0439 \u0433\u043b\u0438\u043d\u044b, \u0438 \u0432\u043e\u0439\u0441\u043a\u043e \u0410\u0431\u0440\u0430\u0445\u0438 \u043f\u043e\u0433\u0438\u0431\u043b\u043e. \u041e\u0431 \u044d\u0442\u043e\u043c \u0440\u0430\u0441\u0441\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u0441\u0443\u0440\u0430 \xab\u0410\u043b\u044c-\u0424\u0438\u043b\u044c\xbb. \u0412 \u044d\u0442\u043e\u0442 \u0433\u043e\u0434 \u0438 \u0440\u043e\u0434\u0438\u043b\u0441\u044f \u041f\u0440\u043e\u0440\u043e\u043a \ufdfa.")
B.aiN=new A.t("\u0414\u0435\u0442\u0441\u0442\u0432\u043e","\u0420\u043e\u0436\u0434\u0435\u043d\u0438\u0435","\u041f\u0440\u043e\u0440\u043e\u043a \u041c\u0443\u0445\u0430\u043c\u043c\u0430\u0434 \ufdfa \u0440\u043e\u0434\u0438\u043b\u0441\u044f \u0432 \u041c\u0435\u043a\u043a\u0435 \u0432 \u043f\u043e\u043d\u0435\u0434\u0435\u043b\u044c\u043d\u0438\u043a \u043c\u0435\u0441\u044f\u0446\u0430 \u0440\u0430\u0431\u0438 \u0430\u043b\u044c-\u0430\u0432\u0432\u0430\u043b\u044c \u0432 \u0413\u043e\u0434 \u0441\u043b\u043e\u043d\u0430 \u2014 \u043e\u043a\u043e\u043b\u043e 570 \u0433\u043e\u0434\u0430. \u041a\u043e\u0433\u0434\u0430 \u0435\u0433\u043e \u0441\u043f\u0440\u043e\u0441\u0438\u043b\u0438 \u043e \u043f\u043e\u0441\u0442\u0435 \u043f\u043e \u043f\u043e\u043d\u0435\u0434\u0435\u043b\u044c\u043d\u0438\u043a\u0430\u043c, \u043e\u043d \u0441\u043a\u0430\u0437\u0430\u043b: \xab\u0412 \u044d\u0442\u043e\u0442 \u0434\u0435\u043d\u044c \u044f \u0440\u043e\u0434\u0438\u043b\u0441\u044f\xbb (\u041c\u0443\u0441\u043b\u0438\u043c).")
B.ako=new A.t("\u0414\u0435\u0442\u0441\u0442\u0432\u043e","\u0418\u043c\u044f \u041c\u0443\u0445\u0430\u043c\u043c\u0430\u0434","\u0414\u0435\u0434 \u0410\u0431\u0434\u0443\u043b\u044c-\u041c\u0443\u0442\u0442\u0430\u043b\u0438\u0431 \u0441 \u0440\u0430\u0434\u043e\u0441\u0442\u044c\u044e \u0432\u0437\u044f\u043b \u0432\u043d\u0443\u043a\u0430 \u043d\u0430 \u0440\u0443\u043a\u0438, \u043e\u0442\u043d\u0451\u0441 \u043a \u041a\u0430\u0430\u0431\u0435 \u0438 \u043d\u0430\u0437\u0432\u0430\u043b \u0435\u0433\u043e \u041c\u0443\u0445\u0430\u043c\u043c\u0430\u0434\u043e\u043c \u2014 \xab\u0432\u043e\u0441\u0445\u0432\u0430\u043b\u044f\u0435\u043c\u044b\u043c\xbb. \u042d\u0442\u043e \u0438\u043c\u044f \u0431\u044b\u043b\u043e \u0440\u0435\u0434\u043a\u0438\u043c \u0443 \u0430\u0440\u0430\u0431\u043e\u0432 \u0442\u043e\u0433\u043e \u0432\u0440\u0435\u043c\u0435\u043d\u0438.")
