B.ali=new A.t("\u0414\u0435\u0442\u0441\u0442\u0432\u043e","\u0421\u043c\u0435\u0440\u0442\u044c \u043c\u0430\u0442\u0435\u0440\u0438","\u041a\u043e\u0433\u0434\u0430 \u041c\u0443\u0445\u0430\u043c\u043c\u0430\u0434\u0443 \ufdfa \u0431\u044b\u043b\u043e \u043e\u043a\u043e\u043b\u043e \u0448\u0435\u0441\u0442\u0438 \u043b\u0435\u0442, \u0410\u043c\u0438\u043d\u0430 \u0432\u0437\u044f\u043b\u0430 \u0435\u0433\u043e \u0432 \u042f\u0441\u0440\u0438\u0431 \u043d\u0430\u0432\u0435\u0441\u0442\u0438\u0442\u044c \u0440\u043e\u0434\u043d\u044b\u0445. \u041d\u0430 \u043e\u0431\u0440\u0430\u0442\u043d\u043e\u043c \u043f\u0443\u0442\u0438, \u0432 \u043c\u0435\u0441\u0442\u0435\u0447\u043a\u0435 \u0410\u0431\u0432\u0430, \u043e\u043d\u0430 \u0437\u0430\u0431\u043e\u043b\u0435\u043b\u0430 \u0438 \u0443\u043c\u0435\u0440\u043b\u0430. \u041c\u0430\u043b\u044c\u0447\u0438\u043a \u043e\u0441\u0442\u0430\u043b\u0441\u044f \u043a\u0440\u0443\u0433\u043b\u044b\u043c \u0441\u0438\u0440\u043e\u0442\u043e\u0439.")
B.aj1=new A.t("\u0414\u0435\u0442\u0441\u0442\u0432\u043e","\u0423\u043c\u043c \u0410\u0439\u043c\u0430\u043d","\u0421\u043b\u0443\u0436\u0430\u043d\u043a\u0430 \u0423\u043c\u043c \u0410\u0439\u043c\u0430\u043d \u043f\u0440\u0438\u0432\u0435\u0437\u043b\u0430 \u043c\u0430\u043b\u044c\u0447\u0438\u043a\u0430 \u0432 \u041c\u0435\u043a\u043a\u0443 \u0438 \u0432\u0441\u044e \u0436\u0438\u0437\u043d\u044c \u0437\u0430\u0431\u043e\u0442\u0438\u043b\u0430\u0441\u044c \u043e \u043d\u0451\u043c. \u041f\u0440\u043e\u0440\u043e\u043a \ufdfa \u043d\u0430\u0437\u044b\u0432\u0430\u043b \u0435\u0451 \xab\u043c\u043e\u044f \u043c\u0430\u0442\u044c \u043f\u043e\u0441\u043b\u0435 \u043c\u043e\u0435\u0439 \u043c\u0430\u0442\u0435\u0440\u0438\xbb.")
B.alV=new A.t("\u0414\u0435\u0442\u0441\u0442\u0432\u043e","\u0414\u0435\u0434 \u0410\u0431\u0434\u0443\u043b\u044c-\u041c\u0443\u0442\u0442\u0430\u043b\u0438\u0431","\u0421\u0438\u0440\u043e\u0442\u0443 \u0432\u0437\u044f\u043b \u043a \u0441\u0435\u0431\u0435 \u0434\u0435\u0434. \u041e\u043d \u043e\u0447\u0435\u043d\u044c \u043b\u044e\u0431\u0438\u043b \u0432\u043d\u0443\u043a\u0430, \u0441\u0430\u0436\u0430\u043b \u0435\u0433\u043e \u0440\u044f\u0434\u043e\u043c \u0441 \u0441\u043e\u0431\u043e\u0439 \u043d\u0430 \u043f\u043e\u0447\u0451\u0442\u043d\u043e\u0435 \u043c\u0435\u0441\u0442\u043e \u0443 \u041a\u0430\u0430\u0431\u044b, \u043a\u0443\u0434\u0430 \u043d\u0435 \u0441\u0430\u0434\u0438\u043b\u0438\u0441\u044c \u0434\u0430\u0436\u0435 \u0435\u0433\u043e \u0441\u044b\u043d\u043e\u0432\u044c\u044f. \u0427\u0435\u0440\u0435\u0437 \u0434\u0432\u0430 \u0433\u043e\u0434\u0430, \u043a\u043e\u0433\u0434\u0430 \u043c\u0430\u043b\u044c\u0447\u0438\u043a\u0443 \u0431\u044b\u043b\u043e \u0432\u043e\u0441\u0435\u043c\u044c, \u0434\u0435\u0434 \u0443\u043c\u0435\u0440.")
