B.alN=new A.t("\u042e\u043d\u043e\u0441\u0442\u044c","\u0414\u0435\u0442\u0438 \u041f\u0440\u043e\u0440\u043e\u043a\u0430 \ufdfa","\u041e\u0442 \u0425\u0430\u0434\u0438\u0434\u0436\u0438 \u0443 \u041f\u0440\u043e\u0440\u043e\u043a\u0430 \ufdfa \u0440\u043e\u0434\u0438\u043b\u0438\u0441\u044c \u0441\u044b\u043d\u043e\u0432\u044c\u044f \u041a\u0430\u0441\u0438\u043c \u0438 \u0410\u0431\u0434\u0443\u043b\u043b\u0430\u0445, \u0443\u043c\u0435\u0440\u0448\u0438\u0435 \u0432 \u0434\u0435\u0442\u0441\u0442\u0432\u0435, \u0438 \u0434\u043e\u0447\u0435\u0440\u0438 \u0417\u0435\u0439\u043d\u0430\u0431, \u0420\u0443\u043a\u0430\u0439\u044f, \u0423\u043c\u043c \u041a\u0443\u043b\u044c\u0441\u0443\u043c \u0438 \u0424\u0430\u0442\u0438\u043c\u0430. \u041f\u043e\u044d\u0442\u043e\u043c\u0443 \u0435\u0433\u043e \u043d\u0430\u0437\u044b\u0432\u0430\u043b\u0438 \u0410\u0431\u0443\u043b\u044c-\u041a\u0430\u0441\u0438\u043c \u2014 \xab\u043e\u0442\u0435\u0446 \u041a\u0430\u0441\u0438\u043c\u0430\xbb.")
B.akF=new A.t("\u042e\u043d\u043e\u0441\u0442\u044c","\u0427\u0451\u0440\u043d\u044b\u0439 \u043a\u0430\u043c\u0435\u043d\u044c","\u041a\u043e\u0433\u0434\u0430 \u041f\u0440\u043e\u0440\u043e\u043a\u0443 \ufdfa \u0431\u044b\u043b\u043e 35 \u043b\u0435\u0442, \u043a\u0443\u0440\u0430\u0439\u0448\u0438\u0442\u044b \u043f\u0435\u0440\u0435\u0441\u0442\u0440\u0430\u0438\u0432\u0430\u043b\u0438 \u041a\u0430\u0430\u0431\u0443 \u0438 \u043f\u043e\u0441\u043f\u043e\u0440\u0438\u043b\u0438, \u043a\u0442\u043e \u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442 \u043d\u0430 \u043c\u0435\u0441\u0442\u043e \u0427\u0451\u0440\u043d\u044b\u0439 \u043a\u0430\u043c\u0435\u043d\u044c. \u0420\u0435\u0448\u0438\u043b\u0438: \u043f\u0443\u0441\u0442\u044c \u0440\u0430\u0441\u0441\u0443\u0434\u0438\u0442 \u043f\u0435\u0440\u0432\u044b\u0439, \u043a\u0442\u043e \u0432\u043e\u0439\u0434\u0451\u0442. \u0412\u043e\u0448\u0451\u043b \u041c\u0443\u0445\u0430\u043c\u043c\u0430\u0434 \ufdfa. \u041e\u043d \u043f\u043e\u043b\u043e\u0436\u0438\u043b \u043a\u0430\u043c\u0435\u043d\u044c \u043d\u0430 \u043f\u043b\u0430\u0449, \u0432\u0441\u0435 \u0441\u0442\u0430\u0440\u0435\u0439\u0448\u0438\u043d\u044b \u043f\u043e\u0434\u043d\u044f\u043b\u0438 \u043f\u043b\u0430\u0449 \u0432\u043c\u0435\u0441\u0442\u0435, \u0430 \u043e\u043d \u0441\u0430\u043c \u043f\u043e\u0441\u0442\u0430\u0432\u0438\u043b \u043a\u0430\u043c\u0435\u043d\u044c \u043d\u0430 \u043c\u0435\u0441\u0442\u043e. \u0421\u043f\u043e\u0440 \u0431\u044b\u043b \u0440\u0435\u0448\u0451\u043d \u043c\u0438\u0440\u043e\u043c.")
B.ai4=new A.t("\u042e\u043d\u043e\u0441\u0442\u044c","\u0417\u0435\u0439\u0434 \u0438\u0431\u043d \u0425\u0430\u0440\u0438\u0441\u0430","\u0425\u0430\u0434\u0438\u0434\u0436\u0430 \u043f\u043e\u0434\u0430\u0440\u0438\u043b\u0430 \u043c\u0443\u0436\u0443 \u044e\u043d\u043e\u0433\u043e \u0441\u043b\u0443\u0433\u0443 \u0417\u0435\u0439\u0434\u0430. \u041f\u0440\u043e\u0440\u043e\u043a \ufdfa \u043e\u0441\u0432\u043e\u0431\u043e\u0434\u0438\u043b \u0435\u0433\u043e \u0438 \u0443\u0441\u044b\u043d\u043e\u0432\u0438\u043b. \u041a\u043e\u0433\u0434\u0430 \u0440\u043e\u0434\u043d\u044b\u0435 \u0417\u0435\u0439\u0434\u0430 \u043d\u0430\u0448\u043b\u0438 \u0435\u0433\u043e \u0438 \u0445\u043e\u0442\u0435\u043b\u0438 \u0437\u0430\u0431\u0440\u0430\u0442\u044c, \u0417\u0435\u0439\u0434 \u0432\u044b\u0431\u0440\u0430\u043b \u043e\u0441\u0442\u0430\u0442\u044c\u0441\u044f \u0441 \u041f\u0440\u043e\u0440\u043e\u043a\u043e\u043c \ufdfa.")
B.alC=new A.t("\u042e\u043d\u043e\u0441\u0442\u044c","\u0410\u043b\u0438 \u0432 \u0434\u043e\u043c\u0435 \u041f\u0440\u043e\u0440\u043e\u043a\u0430 \ufdfa","\u0412 \u0442\u0440\u0443\u0434\u043d\u044b\u0439 \u0433\u043e\u0434 \u041f\u0440\u043e\u0440\u043e\u043a \ufdfa \u0432\u0437\u044f\u043b \u043a \u0441\u0435\u0431\u0435 \u043c\u0430\u043b\u0435\u043d\u044c\u043a\u043e\u0433\u043e \u0410\u043b\u0438, \u0441\u044b\u043d\u0430 \u0410\u0431\u0443 \u0422\u0430\u043b\u0438\u0431\u0430, \u0447\u0442\u043e\u0431\u044b \u043e\u0431\u043b\u0435\u0433\u0447\u0438\u0442\u044c \u0434\u044f\u0434\u0435 \u0436\u0438\u0437\u043d\u044c. \u0410\u043b\u0438 \u0432\u044b\u0440\u043e\u0441 \u0432 \u0435\u0433\u043e \u0434\u043e\u043c\u0435.")
B.aiU=new A.t("\u042e\u043d\u043e\u0441\u0442\u044c","\u0423\u0435\u0434\u0438\u043d\u0435\u043d\u0438\u0435 \u0432 \u0425\u0438\u0440\u0430","\u041f\u0440\u0438\u0431\u043b\u0438\u0436\u0430\u044f\u0441\u044c \u043a \u0441\u043e\u0440\u043e\u043a\u0430 \u0433\u043e\u0434\u0430\u043c, \u041f\u0440\u043e\u0440\u043e\u043a \ufdfa \u043f\u043e\u043b\u044e\u0431\u0438\u043b \u0443\u0435\u0434\u0438\u043d\u0435\u043d\u0438\u0435. \u041e\u043d \u0443\u0445\u043e\u0434\u0438\u043b \u0432 \u043f\u0435\u0449\u0435\u0440\u0443 \u0425\u0438\u0440\u0430 \u043d\u0430 \u0433\u043e\u0440\u0435 \u041d\u0443\u0440 \u0438 \u043f\u0440\u043e\u0432\u043e\u0434\u0438\u043b \u0442\u0430\u043c \u0434\u043d\u0438 \u0432 \u0440\u0430\u0437\u043c\u044b\u0448\u043b\u0435\u043d\u0438\u044f\u0445 \u043e \u0421\u043e\u0437\u0434\u0430\u0442\u0435\u043b\u0435, \u0431\u0435\u0440\u044f \u0441 \u0441\u043e\u0431\u043e\u0439 \u043d\u0435\u043c\u043d\u043e\u0433\u043e \u0435\u0434\u044b.")
B.akm=new A.t("\u041d\u0430\u0447\u0430\u043b\u043e \u043e\u0442\u043a\u0440\u043e\u0432\u0435\u043d\u0438\u044f","\u041f\u0435\u0440\u0432\u043e\u0435 \u043e\u0442\u043a\u0440\u043e\u0432\u0435\u043d\u0438\u0435","\u0412 \u043c\u0435\u0441\u044f\u0446 \u0420\u0430\u043c\u0430\u0434\u0430\u043d, \u043a\u043e\u0433\u0434\u0430 \u041f\u0440\u043e\u0440\u043e\u043a\u0443 \ufdfa \u0431\u044b\u043b\u043e 40 \u043b\u0435\u0442, \u043a \u043d\u0435\u043c\u0443 \u0432 \u043f\u0435\u0449\u0435\u0440\u0443 \u0425\u0438\u0440\u0430 \u043f\u0440\u0438\u0448\u0451\u043b \u0430\u043d\u0433\u0435\u043b \u0414\u0436\u0438\u0431\u0440\u0438\u043b\u044c \u0438 \u0441\u043a\u0430\u0437\u0430\u043b: \xab\u0427\u0438\u0442\u0430\u0439!\xbb \u041e\u043d \u043e\u0442\u0432\u0435\u0442\u0438\u043b: \xab\u042f \u043d\u0435 \u0443\u043c\u0435\u044e \u0447\u0438\u0442\u0430\u0442\u044c\xbb. \u0422\u0430\u043a \u0431\u044b\u043b\u0438 \u043d\u0438\u0441\u043f\u043e\u0441\u043b\u0430\u043d\u044b \u043f\u0435\u0440\u0432\u044b\u0435 \u0430\u044f\u0442\u044b: \xab\u0427\u0438\u0442\u0430\u0439 \u0432\u043e \u0438\u043c\u044f \u0413\u043e\u0441\u043f\u043e\u0434\u0430 \u0442\u0432\u043e\u0435\u0433\u043e, \u041a\u043e\u0442\u043e\u0440\u044b\u0439 \u0441\u043e\u0442\u0432\u043e\u0440\u0438\u043b\u2026\xbb (96:1\u20135).")
B.ahs=new A.t("\u041d\u0430\u0447\u0430\u043b\u043e \u043e\u0442\u043a\u0440\u043e\u0432\u0435\u043d\u0438\u044f","\u0425\u0430\u0434\u0438\u0434\u0436\u0430 \u0443\u0442\u0435\u0448\u0430\u0435\u0442","\u0412\u0437\u0432\u043e\u043b\u043d\u043e\u0432\u0430\u043d\u043d\u044b\u0439, \u041f\u0440\u043e\u0440\u043e\u043a \ufdfa \u0432\u0435\u0440\u043d\u0443\u043b\u0441\u044f \u0434\u043e\u043c\u043e\u0439 \u0438 \u0441\u043a\u0430\u0437\u0430\u043b: \xab\u0423\u043a\u0440\u043e\u0439\u0442\u0435 \u043c\u0435\u043d\u044f!\xbb \u0425\u0430\u0434\u0438\u0434\u0436\u0430 \u0443\u0441\u043f\u043e\u043a\u043e\u0438\u043b\u0430 \u0435\u0433\u043e: \xab\u0410\u043b\u043b\u0430\u0445 \u043d\u0438\u043a\u043e\u0433\u0434\u0430 \u043d\u0435 \u043e\u043f\u043e\u0437\u043e\u0440\u0438\u0442 \u0442\u0435\u0431\u044f: \u0442\u044b \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u0448\u044c \u0440\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u0438\u043a\u043e\u0432, \u043f\u043e\u043c\u043e\u0433\u0430\u0435\u0448\u044c \u0441\u043b\u0430\u0431\u044b\u043c, \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u0448\u044c \u0433\u043e\u0441\u0442\u0435\u0439 \u0438 \u043f\u043e\u043c\u043e\u0433\u0430\u0435\u0448\u044c \u0432 \u0431\u0435\u0434\u0430\u0445\xbb (\u0411\u0443\u0445\u0430\u0440\u0438).")
B.ami=new A.t("\u041d\u0430\u0447\u0430\u043b\u043e \u043e\u0442\u043a\u0440\u043e\u0432\u0435\u043d\u0438\u044f","\u0412\u0430\u0440\u0430\u043a\u0430 \u0438\u0431\u043d \u041d\u0430\u0443\u0444\u0430\u043b\u044c","\u0425\u0430\u0434\u0438\u0434\u0436\u0430 \u043e\u0442\u0432\u0435\u043b\u0430 \u043c\u0443\u0436\u0430 \u043a \u0441\u0432\u043e\u0435\u043c\u0443 \u0434\u0432\u043e\u044e\u0440\u043e\u0434\u043d\u043e\u043c\u0443 \u0431\u0440\u0430\u0442\u0443 \u0412\u0430\u0440\u0430\u043a\u0435 \u2014 \u0437\u043d\u0430\u0442\u043e\u043a\u0443 \u043f\u0440\u0435\u0436\u043d\u0438\u0445 \u041f\u0438\u0441\u0430\u043d\u0438\u0439. \u0412\u044b\u0441\u043b\u0443\u0448\u0430\u0432, \u0412\u0430\u0440\u0430\u043a\u0430 \u0441\u043a\u0430\u0437\u0430\u043b, \u0447\u0442\u043e \u043a \u043d\u0435\u043c\u0443 \u043f\u0440\u0438\u0445\u043e\u0434\u0438\u043b \u0442\u043e\u0442 \u0436\u0435 \u0430\u043d\u0433\u0435\u043b, \u0447\u0442\u043e \u0438 \u043a \u041c\u0443\u0441\u0435, \u0438 \u0447\u0442\u043e \u043d\u0430\u0440\u043e\u0434 \u0438\u0437\u0433\u043e\u043d\u0438\u0442 \u0435\u0433\u043e.")
B.akE=new A.t("\u041d\u0430\u0447\u0430\u043b\u043e \u043e\u0442\u043a\u0440\u043e\u0432\u0435\u043d\u0438\u044f","\u041f\u0435\u0440\u0432\u044b\u0435 \u043c\u0443\u0441\u0443\u043b\u044c\u043c\u0430\u043d\u0435","\u041f\u0435\u0440\u0432\u043e\u0439 \u0443\u0432\u0435\u0440\u043e\u0432\u0430\u043b\u0430 \u0425\u0430\u0434\u0438\u0434\u0436\u0430. \u0418\u0437 \u0434\u0435\u0442\u0435\u0439 \u043f\u0435\u0440\u0432\u044b\u043c \u043f\u0440\u0438\u043d\u044f\u043b \u0438\u0441\u043b\u0430\u043c \u0410\u043b\u0438, \u0438\u0437 \u043e\u0441\u0432\u043e\u0431\u043e\u0436\u0434\u0451\u043d\u043d\u044b\u0445 \u2014 \u0417\u0435\u0439\u0434, \u0438\u0437 \u0432\u0437\u0440\u043e\u0441\u043b\u044b\u0445 \u043c\u0443\u0436\u0447\u0438\u043d \u2014 \u0410\u0431\u0443 \u0411\u0430\u043a\u0440. \u041f\u0435\u0440\u0432\u044b\u0435 \u0442\u0440\u0438 \u0433\u043e\u0434\u0430 \u043f\u0440\u0438\u0437\u044b\u0432 \u0448\u0451\u043b \u0442\u0430\u0439\u043d\u043e, \u0441\u0440\u0435\u0434\u0438 \u0431\u043b\u0438\u0437\u043a\u0438\u0445.")
B.alv=new A.t("\u041d\u0430\u0447\u0430\u043b\u043e \u043e\u0442\u043a\u0440\u043e\u0432\u0435\u043d\u0438\u044f","\u0410\u0431\u0443 \u0411\u0430\u043a\u0440 \u043f\u0440\u0438\u0432\u043e\u0434\u0438\u0442 \u0434\u0440\u0443\u0437\u0435\u0439","\u0410\u0431\u0443 \u0411\u0430\u043a\u0440, \u0443\u0432\u0430\u0436\u0430\u0435\u043c\u044b\u0439 \u0442\u043e\u0440\u0433\u043e\u0432\u0435\u0446, \u0441\u0440\u0430\u0437\u0443 \u0441\u0442\u0430\u043b \u043f\u0440\u0438\u0437\u044b\u0432\u0430\u0442\u044c \u0434\u0440\u0443\u0433\u0438\u0445. \u0427\u0435\u0440\u0435\u0437 \u043d\u0435\u0433\u043e \u0438\u0441\u043b\u0430\u043c \u043f\u0440\u0438\u043d\u044f\u043b\u0438 \u0423\u0441\u043c\u0430\u043d \u0438\u0431\u043d \u0410\u0444\u0444\u0430\u043d, \u0417\u0443\u0431\u0430\u0439\u0440, \u0410\u0431\u0434\u0443\u0440\u0440\u0430\u0445\u043c\u0430\u043d \u0438\u0431\u043d \u0410\u0443\u0444, \u0421\u0430\u0430\u0434 \u0438\u0431\u043d \u0410\u0431\u0443 \u0412\u0430\u043a\u043a\u0430\u0441 \u0438 \u0422\u0430\u043b\u044c\u0445\u0430.")
B.amn=new A.t("\u041d\u0430\u0447\u0430\u043b\u043e \u043e\u0442\u043a\u0440\u043e\u0432\u0435\u043d\u0438\u044f","\u0414\u043e\u043c \u0430\u043b\u044c-\u0410\u0440\u043a\u0430\u043c\u0430","\u041c\u0443\u0441\u0443\u043b\u044c\u043c\u0430\u043d\u0435 \u0442\u0430\u0439\u043d\u043e \u0441\u043e\u0431\u0438\u0440\u0430\u043b\u0438\u0441\u044c \u0432 \u0434\u043e\u043c\u0435 \u0441\u043f\u043e\u0434\u0432\u0438\u0436\u043d\u0438\u043a\u0430 \u0430\u043b\u044c-\u0410\u0440\u043a\u0430\u043c\u0430 \u0443 \u0445\u043e\u043b\u043c\u0430 \u0421\u0430\u0444\u0430. \u0422\u0430\u043c \u041f\u0440\u043e\u0440\u043e\u043a \ufdfa \u0443\u0447\u0438\u043b \u0438\u0445 \u041a\u043e\u0440\u0430\u043d\u0443 \u0438 \u043c\u043e\u043b\u0438\u0442\u0432\u0435.")
B.ahP=new A.t("\u041d\u0430\u0447\u0430\u043b\u043e \u043e\u0442\u043a\u0440\u043e\u0432\u0435\u043d\u0438\u044f","\u041f\u0440\u0438\u0437\u044b\u0432 \u0441 \u0445\u043e\u043b\u043c\u0430 \u0421\u0430\u0444\u0430","\u041a\u043e\u0433\u0434\u0430 \u043f\u0440\u0438\u0448\u043b\u043e \u043f\u043e\u0432\u0435\u043b\u0435\u043d\u0438\u0435 \u043f\u0440\u0438\u0437\u044b\u0432\u0430\u0442\u044c \u043e\u0442\u043a\u0440\u044b\u0442\u043e, \u041f\u0440\u043e\u0440\u043e\u043a \ufdfa \u043f\u043e\u0434\u043d\u044f\u043b\u0441\u044f \u043d\u0430 \u0445\u043e\u043b\u043c \u0421\u0430\u0444\u0430 \u0438 \u0441\u043e\u0437\u0432\u0430\u043b \u043a\u0443\u0440\u0430\u0439\u0448\u0438\u0442\u043e\u0432: \xab\u0415\u0441\u043b\u0438 \u044f \u0441\u043a\u0430\u0436\u0443, \u0447\u0442\u043e \u0437\u0430 \u044d\u0442\u0438\u043c \u0445\u043e\u043b\u043c\u043e\u043c \u043a\u043e\u043d\u043d\u0438\u0446\u0430, \u043f\u043e\u0432\u0435\u0440\u0438\u0442\u0435?\xbb \u2014 \xab\u041c\u044b \u043d\u0438\u043a\u043e\u0433\u0434\u0430 \u043d\u0435 \u0441\u043b\u044b\u0448\u0430\u043b\u0438 \u043e\u0442 \u0442\u0435\u0431\u044f \u043b\u0436\u0438\xbb. \u2014 \xab\u042f \u043f\u0440\u0435\u0434\u043e\u0441\u0442\u0435\u0440\u0435\u0433\u0430\u044e \u0432\u0430\u0441 \u043f\u0435\u0440\u0435\u0434 \u0442\u044f\u0436\u043a\u0438\u043c \u043d\u0430\u043a\u0430\u0437\u0430\u043d\u0438\u0435\u043c\xbb (\u0411\u0443\u0445\u0430\u0440\u0438).")
B.ahE=new A.t("\u041d\u0430\u0447\u0430\u043b\u043e \u043e\u0442\u043a\u0440\u043e\u0432\u0435\u043d\u0438\u044f","\u0410\u0431\u0443 \u041b\u0430\u0445\u0430\u0431","\u0414\u044f\u0434\u044f \u041f\u0440\u043e\u0440\u043e\u043a\u0430 \ufdfa \u0410\u0431\u0443 \u041b\u0430\u0445\u0430\u0431 \u043f\u0435\u0440\u0432\u044b\u043c \u0433\u0440\u0443\u0431\u043e \u043e\u0442\u0432\u0435\u0440\u0433 \u043f\u0440\u0438\u0437\u044b\u0432. \u041e \u043d\u0451\u043c \u0438 \u0435\u0433\u043e \u0436\u0435\u043d\u0435, \u043a\u043e\u0442\u043e\u0440\u0430\u044f \u0440\u0430\u0437\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u043b\u0430 \u043a\u043e\u043b\u044e\u0447\u043a\u0438 \u043d\u0430 \u043f\u0443\u0442\u0438 \u041f\u0440\u043e\u0440\u043e\u043a\u0430 \ufdfa, \u043d\u0438\u0441\u043f\u043e\u0441\u043b\u0430\u043d\u0430 \u0441\u0443\u0440\u0430 \xab\u0410\u043b\u044c-\u041c\u0430\u0441\u0430\u0434\xbb.")
B.ahv=new A.t("\u041d\u0430\u0447\u0430\u043b\u043e \u043e\u0442\u043a\u0440\u043e\u0432\u0435\u043d\u0438\u044f","\u041d\u0430\u0441\u043c\u0435\u0448\u043a\u0438 \u0438 \u043a\u043b\u0435\u0432\u0435\u0442\u0430","\u041a\u0443\u0440\u0430\u0439\u0448\u0438\u0442\u044b \u043d\u0430\u0437\u044b\u0432\u0430\u043b\u0438 \u041f\u0440\u043e\u0440\u043e\u043a\u0430 \ufdfa \u0442\u043e \u043f\u043e\u044d\u0442\u043e\u043c, \u0442\u043e \u043a\u043e\u043b\u0434\u0443\u043d\u043e\u043c, \u0442\u043e \u0431\u0435\u0437\u0443\u043c\u0446\u0435\u043c. \u041d\u043e \u043b\u044e\u0434\u0438, \u0441\u043b\u044b\u0448\u0430\u0432\u0448\u0438\u0435 \u041a\u043e\u0440\u0430\u043d, \u043f\u043e\u043d\u0438\u043c\u0430\u043b\u0438, \u0447\u0442\u043e \u044d\u0442\u043e \u043d\u0435 \u0441\u043b\u043e\u0432\u0430 \u0447\u0435\u043b\u043e\u0432\u0435\u043a\u0430.")
B.alz=new A.t("\u041d\u0430\u0447\u0430\u043b\u043e \u043e\u0442\u043a\u0440\u043e\u0432\u0435\u043d\u0438\u044f","\u0411\u0438\u043b\u0430\u043b","\u0425\u043e\u0437\u044f\u0438\u043d \u0411\u0438\u043b\u0430\u043b\u0430, \u0423\u043c\u0430\u0439\u044f, \u0432\u044b\u043d\u043e\u0441\u0438\u043b \u0435\u0433\u043e \u0432 \u0436\u0430\u0440\u0443 \u043d\u0430 \u0440\u0430\u0441\u043a\u0430\u043b\u0451\u043d\u043d\u044b\u0439 \u043f\u0435\u0441\u043e\u043a \u0438 \u043a\u043b\u0430\u043b \u043d\u0430 \u0433\u0440\u0443\u0434\u044c \u043a\u0430\u043c\u0435\u043d\u044c, \u0442\u0440\u0435\u0431\u0443\u044f \u043e\u0442\u0440\u0435\u0447\u044c\u0441\u044f. \u0411\u0438\u043b\u0430\u043b \u043f\u043e\u0432\u0442\u043e\u0440\u044f\u043b: \xab\u0410\u0445\u0430\u0434, \u0410\u0445\u0430\u0434\xbb \u2014 \xab\u0415\u0434\u0438\u043d, \u0415\u0434\u0438\u043d\xbb. \u0410\u0431\u0443 \u0411\u0430\u043a\u0440 \u0432\u044b\u043a\u0443\u043f\u0438\u043b \u0438 \u043e\u0441\u0432\u043e\u0431\u043e\u0434\u0438\u043b \u0435\u0433\u043e.")
B.aip=new A.t("\u041d\u0430\u0447\u0430\u043b\u043e \u043e\u0442\u043a\u0440\u043e\u0432\u0435\u043d\u0438\u044f","\u0421\u0435\u043c\u044c\u044f \u042f\u0441\u0438\u0440\u0430","\u042f\u0441\u0438\u0440\u0430, \u0435\u0433\u043e \u0436\u0435\u043d\u0443 \u0421\u0443\u043c\u0430\u0439\u044e \u0438 \u0441\u044b\u043d\u0430 \u0410\u043c\u043c\u0430\u0440\u0430 \u0436\u0435\u0441\u0442\u043e\u043a\u043e \u043f\u044b\u0442\u0430\u043b\u0438 \u0437\u0430 \u0432\u0435\u0440\u0443. \u041f\u0440\u043e\u0440\u043e\u043a \ufdfa, \u043f\u0440\u043e\u0445\u043e\u0434\u044f \u043c\u0438\u043c\u043e, \u0433\u043e\u0432\u043e\u0440\u0438\u043b: \xab\u0422\u0435\u0440\u043f\u0435\u043d\u0438\u0435, \u0441\u0435\u043c\u044c\u044f \u042f\u0441\u0438\u0440\u0430, \u0432\u0430\u043c \u043e\u0431\u0435\u0449\u0430\u043d \u0420\u0430\u0439\xbb. \u0421\u0443\u043c\u0430\u0439\u044f \u0441\u0442\u0430\u043b\u0430 \u043f\u0435\u0440\u0432\u043e\u0439 \u0448\u0430\u0445\u0438\u0434\u043a\u043e\u0439 \u0438\u0441\u043b\u0430\u043c\u0430.")
B.ahM=new A.t("\u041d\u0430\u0447\u0430\u043b\u043e \u043e\u0442\u043a\u0440\u043e\u0432\u0435\u043d\u0438\u044f","\u041f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u043a\u0443\u0440\u0430\u0439\u0448\u0438\u0442\u043e\u0432","\u041a\u0443\u0440\u0430\u0439\u0448\u0438\u0442\u044b \u043f\u0440\u0438\u0441\u043b\u0430\u043b\u0438 \u0423\u0442\u0431\u0443 \u0438\u0431\u043d \u0420\u0430\u0431\u0438\u0443: \xab\u0425\u043e\u0447\u0435\u0448\u044c \u0431\u043e\u0433\u0430\u0442\u0441\u0442\u0432\u0430 \u2014 \u0441\u043e\u0431\u0435\u0440\u0451\u043c \u0442\u0435\u0431\u0435; \u0445\u043e\u0447\u0435\u0448\u044c \u0432\u043b\u0430\u0441\u0442\u0438 \u2014 \u0441\u0434\u0435\u043b\u0430\u0435\u043c \u0446\u0430\u0440\u0451\u043c\xbb. \u041f\u0440\u043e\u0440\u043e\u043a \ufdfa \u0432 \u043e\u0442\u0432\u0435\u0442 \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u043b \u043d\u0430\u0447\u0430\u043b\u043e \u0441\u0443\u0440\u044b \xab\u0424\u0443\u0441\u0441\u044b\u043b\u044f\u0442\xbb, \u0438 \u0423\u0442\u0431\u0430 \u0432\u0435\u0440\u043d\u0443\u043b\u0441\u044f \u043f\u043e\u0442\u0440\u044f\u0441\u0451\u043d\u043d\u044b\u043c.")
B.ahI=new A.t("\u041d\u0430\u0447\u0430\u043b\u043e \u043e\u0442\u043a\u0440\u043e\u0432\u0435\u043d\u0438\u044f","\u0425\u0430\u043c\u0437\u0430 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u0442 \u0438\u0441\u043b\u0430\u043c","\u0410\u0431\u0443 \u0414\u0436\u0430\u0445\u043b\u044c \u043e\u0441\u043a\u043e\u0440\u0431\u0438\u043b \u041f\u0440\u043e\u0440\u043e\u043a\u0430 \ufdfa. \u0423\u0437\u043d\u0430\u0432 \u043e\u0431 \u044d\u0442\u043e\u043c, \u0435\u0433\u043e \u0434\u044f\u0434\u044f \u0425\u0430\u043c\u0437\u0430, \u0445\u0440\u0430\u0431\u0440\u044b\u0439 \u0432\u043e\u0438\u043d, \u043f\u0440\u0438\u0448\u0451\u043b \u043a \u0410\u0431\u0443 \u0414\u0436\u0430\u0445\u043b\u044e, \u0443\u0434\u0430\u0440\u0438\u043b \u0435\u0433\u043e \u043b\u0443\u043a\u043e\u043c \u0438 \u043e\u0431\u044a\u044f\u0432\u0438\u043b: \xab\u042f \u0442\u043e\u0436\u0435 \u0432 \u0435\u0433\u043e \u0440\u0435\u043b\u0438\u0433\u0438\u0438\xbb. \u041a\u0443\u0440\u0430\u0439\u0448\u0438\u0442\u044b \u0441\u0442\u0430\u043b\u0438 \u043e\u0441\u0442\u043e\u0440\u043e\u0436\u043d\u0435\u0435.")
B.ajw=new A.t("\u041d\u0430\u0447\u0430\u043b\u043e \u043e\u0442\u043a\u0440\u043e\u0432\u0435\u043d\u0438\u044f","\u0423\u043c\u0430\u0440 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u0442 \u0438\u0441\u043b\u0430\u043c","\u0423\u043c\u0430\u0440 \u0438\u0431\u043d \u0430\u043b\u044c-\u0425\u0430\u0442\u0442\u0430\u0431 \u0432\u044b\u0448\u0435\u043b, \u0447\u0442\u043e\u0431\u044b \u0443\u0431\u0438\u0442\u044c \u041f\u0440\u043e\u0440\u043e\u043a\u0430 \ufdfa, \u043d\u043e \u0443\u0437\u043d\u0430\u043b, \u0447\u0442\u043e \u0435\u0433\u043e \u0441\u0435\u0441\u0442\u0440\u0430 \u0438 \u0435\u0451 \u043c\u0443\u0436 \u043f\u0440\u0438\u043d\u044f\u043b\u0438 \u0438\u0441\u043b\u0430\u043c. \u041e\u043d \u0443\u0441\u043b\u044b\u0448\u0430\u043b \u0443 \u043d\u0438\u0445 \u0430\u044f\u0442\u044b \u0441\u0443\u0440\u044b \xab\u0422\u0430 \u0425\u0430\xbb, \u0435\u0433\u043e \u0441\u0435\u0440\u0434\u0446\u0435 \u0441\u043c\u044f\u0433\u0447\u0438\u043b\u043e\u0441\u044c, \u0438 \u043e\u043d \u043f\u043e\u0448\u0451\u043b \u043a \u041f\u0440\u043e\u0440\u043e\u043a\u0443 \ufdfa \u043f\u0440\u0438\u043d\u044f\u0442\u044c \u0438\u0441\u043b\u0430\u043c. \u041f\u043e\u0441\u043b\u0435 \u044d\u0442\u043e\u0433\u043e \u043c\u0443\u0441\u0443\u043b\u044c\u043c\u0430\u043d\u0435 \u0441\u0442\u0430\u043b\u0438 \u043c\u043e\u043b\u0438\u0442\u044c\u0441\u044f \u0443 \u041a\u0430\u0430\u0431\u044b \u043e\u0442\u043a\u0440\u044b\u0442\u043e.")
B.ajq=new A.t("\u0413\u043e\u0434\u044b \u0438\u0441\u043f\u044b\u0442\u0430\u043d\u0438\u0439","\u0425\u0438\u0434\u0436\u0440\u0430 \u0432 \u0410\u0431\u0438\u0441\u0441\u0438\u043d\u0438\u044e","\u0421\u043f\u0430\u0441\u0430\u044f\u0441\u044c \u043e\u0442 \u0433\u043e\u043d\u0435\u043d\u0438\u0439, \u0433\u0440\u0443\u043f\u043f\u0430 \u043c\u0443\u0441\u0443\u043b\u044c\u043c\u0430\u043d \u043f\u043e \u0441\u043e\u0432\u0435\u0442\u0443 \u041f\u0440\u043e\u0440\u043e\u043a\u0430 \ufdfa \u043f\u0435\u0440\u0435\u0441\u0435\u043b\u0438\u043b\u0430\u0441\u044c \u0432 \u0410\u0431\u0438\u0441\u0441\u0438\u043d\u0438\u044e, \u0433\u0434\u0435 \u043f\u0440\u0430\u0432\u0438\u043b \u0441\u043f\u0440\u0430\u0432\u0435\u0434\u043b\u0438\u0432\u044b\u0439 \u0445\u0440\u0438\u0441\u0442\u0438\u0430\u043d\u0441\u043a\u0438\u0439 \u0446\u0430\u0440\u044c \u2014 \u041d\u0435\u0433\u0443\u0441. \u0421\u0440\u0435\u0434\u0438 \u043d\u0438\u0445 \u0431\u044b\u043b\u0438 \u0423\u0441\u043c\u0430\u043d \u0441 \u0436\u0435\u043d\u043e\u0439 \u0420\u0443\u043a\u0430\u0439\u0435\u0439, \u0434\u043e\u0447\u0435\u0440\u044c\u044e \u041f\u0440\u043e\u0440\u043e\u043a\u0430 \ufdfa.")
B.alk=new A.t("\u0413\u043e\u0434\u044b \u0438\u0441\u043f\u044b\u0442\u0430\u043d\u0438\u0439","\u0420\u0435\u0447\u044c \u0414\u0436\u0430\u0444\u0430\u0440\u0430","\u041a\u0443\u0440\u0430\u0439\u0448\u0438\u0442\u044b \u043e\u0442\u043f\u0440\u0430\u0432\u0438\u043b\u0438 \u043a \u041d\u0435\u0433\u0443\u0441\u0443 \u043f\u043e\u0441\u043b\u043e\u0432 \u0441 \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u0435\u043c \u0432\u044b\u0434\u0430\u0442\u044c \u0431\u0435\u0433\u043b\u0435\u0446\u043e\u0432. \u0414\u0436\u0430\u0444\u0430\u0440 \u0438\u0431\u043d \u0410\u0431\u0443 \u0422\u0430\u043b\u0438\u0431 \u0440\u0430\u0441\u0441\u043a\u0430\u0437\u0430\u043b \u0446\u0430\u0440\u044e, \u043a\u0430\u043a \u0438\u0441\u043b\u0430\u043c \u0432\u044b\u0432\u0435\u043b \u0438\u0445 \u0438\u0437 \u043d\u0435\u0432\u0435\u0436\u0435\u0441\u0442\u0432\u0430, \u0438 \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u043b \u0430\u044f\u0442\u044b \u0441\u0443\u0440\u044b \xab\u041c\u0430\u0440\u044c\u044f\u043c\xbb. \u041d\u0435\u0433\u0443\u0441 \u0437\u0430\u043f\u043b\u0430\u043a\u0430\u043b \u0438 \u043e\u0442\u043a\u0430\u0437\u0430\u043b\u0441\u044f \u0432\u044b\u0434\u0430\u0442\u044c \u043c\u0443\u0441\u0443\u043b\u044c\u043c\u0430\u043d.")
B.ai6=new A.t("\u0413\u043e\u0434\u044b \u0438\u0441\u043f\u044b\u0442\u0430\u043d\u0438\u0439","\u0411\u043e\u0439\u043a\u043e\u0442","\u041a\u0443\u0440\u0430\u0439\u0448\u0438\u0442\u044b \u043e\u0431\u044a\u044f\u0432\u0438\u043b\u0438 \u0431\u043e\u0439\u043a\u043e\u0442 \u0440\u043e\u0434\u0443 \u0411\u0430\u043d\u0443 \u0425\u0430\u0448\u0438\u043c: \u043d\u0435 \u0442\u043e\u0440\u0433\u043e\u0432\u0430\u0442\u044c \u0441 \u043d\u0438\u043c\u0438 \u0438 \u043d\u0435 \u0432\u0441\u0442\u0443\u043f\u0430\u0442\u044c \u0432 \u0431\u0440\u0430\u043a\u0438. \u041e\u043a\u043e\u043b\u043e \u0442\u0440\u0451\u0445 \u043b\u0435\u0442 \u041f\u0440\u043e\u0440\u043e\u043a \ufdfa, \u0435\u0433\u043e \u0440\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u0438\u043a\u0438 \u0438 \u043c\u0443\u0441\u0443\u043b\u044c\u043c\u0430\u043d\u0435 \u0436\u0438\u043b\u0438 \u0432 \u0443\u0449\u0435\u043b\u044c\u0435 \u0410\u0431\u0443 \u0422\u0430\u043b\u0438\u0431\u0430, \u0442\u0435\u0440\u043f\u044f \u0433\u043e\u043b\u043e\u0434.")
