B.akj=new A.t("\u041c\u0435\u0434\u0438\u043d\u0430","\u0421\u043c\u0435\u043d\u0430 \u043a\u0438\u0431\u043b\u044b","\u041e\u043a\u043e\u043b\u043e \u0448\u0435\u0441\u0442\u043d\u0430\u0434\u0446\u0430\u0442\u0438 \u043c\u0435\u0441\u044f\u0446\u0435\u0432 \u043c\u0443\u0441\u0443\u043b\u044c\u043c\u0430\u043d\u0435 \u043c\u043e\u043b\u0438\u043b\u0438\u0441\u044c \u0432 \u0441\u0442\u043e\u0440\u043e\u043d\u0443 \u0418\u0435\u0440\u0443\u0441\u0430\u043b\u0438\u043c\u0430. \u041f\u0440\u043e\u0440\u043e\u043a \ufdfa \u043d\u0430\u0434\u0435\u044f\u043b\u0441\u044f, \u0447\u0442\u043e \u043a\u0438\u0431\u043b\u043e\u0439 \u0441\u0442\u0430\u043d\u0435\u0442 \u041a\u0430\u0430\u0431\u0430, \u2014 \u0438 \u043f\u0440\u0438\u0448\u043b\u043e \u043f\u043e\u0432\u0435\u043b\u0435\u043d\u0438\u0435 \u043e\u0431\u0440\u0430\u0442\u0438\u0442\u044c\u0441\u044f \u043a \u041c\u0430\u0441\u0434\u0436\u0438\u0434 \u0430\u043b\u044c-\u0425\u0430\u0440\u0430\u043c (2:144).")
B.akN=new A.t("\u041c\u0435\u0434\u0438\u043d\u0430","\u041f\u043e\u0441\u0442 \u0432 \u0420\u0430\u043c\u0430\u0434\u0430\u043d","\u0412\u043e \u0432\u0442\u043e\u0440\u043e\u0439 \u0433\u043e\u0434 \u0445\u0438\u0434\u0436\u0440\u044b \u0431\u044b\u043b \u043f\u0440\u0435\u0434\u043f\u0438\u0441\u0430\u043d \u043f\u043e\u0441\u0442 \u0432 \u043c\u0435\u0441\u044f\u0446 \u0420\u0430\u043c\u0430\u0434\u0430\u043d (2:183\u2013185), \u0430 \u0442\u0430\u043a\u0436\u0435 \u0437\u0430\u043a\u044f\u0442 \u0430\u043b\u044c-\u0444\u0438\u0442\u0440 \u043f\u0435\u0440\u0435\u0434 \u043f\u0440\u0430\u0437\u0434\u043d\u0438\u043a\u043e\u043c.")
B.ahD=new A.t("\u041c\u0435\u0434\u0438\u043d\u0430","\u041f\u0435\u0440\u0435\u0434 \u0411\u0430\u0434\u0440\u043e\u043c","\u0412\u043e \u0432\u0442\u043e\u0440\u043e\u0439 \u0433\u043e\u0434 \u0445\u0438\u0434\u0436\u0440\u044b \u043c\u0443\u0441\u0443\u043b\u044c\u043c\u0430\u043d\u0435 \u0432\u044b\u0448\u043b\u0438 \u043d\u0430\u0432\u0441\u0442\u0440\u0435\u0447\u0443 \u043a\u0430\u0440\u0430\u0432\u0430\u043d\u0443 \u043a\u0443\u0440\u0430\u0439\u0448\u0438\u0442\u043e\u0432, \u0430 \u0432\u0441\u0442\u0440\u0435\u0442\u0438\u043b\u0438 \u0432\u043e\u0439\u0441\u043a\u043e \u043e\u043a\u043e\u043b\u043e \u0442\u044b\u0441\u044f\u0447\u0438 \u0447\u0435\u043b\u043e\u0432\u0435\u043a. \u041c\u0443\u0441\u0443\u043b\u044c\u043c\u0430\u043d \u0431\u044b\u043b\u043e \u043e\u043a\u043e\u043b\u043e 313. \u041f\u0440\u043e\u0440\u043e\u043a \ufdfa \u043f\u043e\u0441\u043e\u0432\u0435\u0442\u043e\u0432\u0430\u043b\u0441\u044f \u0441\u043e \u0441\u043f\u043e\u0434\u0432\u0438\u0436\u043d\u0438\u043a\u0430\u043c\u0438, \u0438 \u0430\u043d\u0441\u0430\u0440\u044b \u0441\u043a\u0430\u0437\u0430\u043b\u0438: \xab\u0412\u0435\u0434\u0438 \u043d\u0430\u0441 \u2014 \u043c\u044b \u0441 \u0442\u043e\u0431\u043e\u0439\xbb.")
B.amo=new A.t("\u041c\u0435\u0434\u0438\u043d\u0430","\u0411\u0438\u0442\u0432\u0430 \u043f\u0440\u0438 \u0411\u0430\u0434\u0440\u0435","\u0412\u0441\u044e \u043d\u043e\u0447\u044c \u043f\u0435\u0440\u0435\u0434 \u0431\u0438\u0442\u0432\u043e\u0439 \u041f\u0440\u043e\u0440\u043e\u043a \ufdfa \u043c\u043e\u043b\u0438\u043b\u0441\u044f. \u0410\u043b\u043b\u0430\u0445 \u043f\u043e\u043c\u043e\u0433 \u043c\u0443\u0441\u0443\u043b\u044c\u043c\u0430\u043d\u0430\u043c \u0430\u043d\u0433\u0435\u043b\u0430\u043c\u0438 (8:9), \u0438 \u043e\u043d\u0438 \u043f\u043e\u0431\u0435\u0434\u0438\u043b\u0438. \u041f\u043e\u0433\u0438\u0431\u043b\u0438 \u043c\u043d\u043e\u0433\u0438\u0435 \u0432\u043e\u0436\u0434\u0438 \u043a\u0443\u0440\u0430\u0439\u0448\u0438\u0442\u043e\u0432, \u0441\u0440\u0435\u0434\u0438 \u043d\u0438\u0445 \u0410\u0431\u0443 \u0414\u0436\u0430\u0445\u043b\u044c. \u042d\u0442\u043e\u0442 \u0434\u0435\u043d\u044c \u041a\u043e\u0440\u0430\u043d \u043d\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u0434\u043d\u0451\u043c \u0440\u0430\u0437\u043b\u0438\u0447\u0435\u043d\u0438\u044f.")
B.al7=new A.t("\u041c\u0435\u0434\u0438\u043d\u0430","\u041f\u043b\u0435\u043d\u043d\u044b\u0435 \u0411\u0430\u0434\u0440\u0430","\u041f\u0440\u043e\u0440\u043e\u043a \ufdfa \u0432\u0435\u043b\u0435\u043b \u0445\u043e\u0440\u043e\u0448\u043e \u043e\u0431\u0440\u0430\u0449\u0430\u0442\u044c\u0441\u044f \u0441 \u043f\u043b\u0435\u043d\u043d\u044b\u043c\u0438. \u041d\u0435\u043a\u043e\u0442\u043e\u0440\u044b\u0445 \u043e\u0442\u043f\u0443\u0441\u0442\u0438\u043b\u0438 \u0437\u0430 \u0432\u044b\u043a\u0443\u043f, \u0430 \u0433\u0440\u0430\u043c\u043e\u0442\u043d\u044b\u0435 \u043c\u043e\u0433\u043b\u0438 \u043e\u0441\u0432\u043e\u0431\u043e\u0434\u0438\u0442\u044c\u0441\u044f, \u043e\u0431\u0443\u0447\u0438\u0432 \u0433\u0440\u0430\u043c\u043e\u0442\u0435 \u0434\u0435\u0441\u044f\u0442\u044c \u0434\u0435\u0442\u0435\u0439 \u041c\u0435\u0434\u0438\u043d\u044b.")
B.ah7=new A.t("\u041c\u0435\u0434\u0438\u043d\u0430","\u0411\u0438\u0442\u0432\u0430 \u043f\u0440\u0438 \u0423\u0445\u0443\u0434\u0435","\u0427\u0435\u0440\u0435\u0437 \u0433\u043e\u0434 \u043a\u0443\u0440\u0430\u0439\u0448\u0438\u0442\u044b \u043f\u0440\u0438\u0448\u043b\u0438 \u043c\u0441\u0442\u0438\u0442\u044c \u0441 \u0432\u043e\u0439\u0441\u043a\u043e\u043c \u0432 \u0442\u0440\u0438 \u0442\u044b\u0441\u044f\u0447\u0438. \u0423 \u0433\u043e\u0440\u044b \u0423\u0445\u0443\u0434 \u041f\u0440\u043e\u0440\u043e\u043a \ufdfa \u043f\u043e\u0441\u0442\u0430\u0432\u0438\u043b \u043f\u044f\u0442\u044c\u0434\u0435\u0441\u044f\u0442 \u043b\u0443\u0447\u043d\u0438\u043a\u043e\u0432 \u0438 \u0432\u0435\u043b\u0435\u043b \u043d\u0435 \u043f\u043e\u043a\u0438\u0434\u0430\u0442\u044c \u043c\u0435\u0441\u0442\u043e \u043d\u0438 \u043f\u0440\u0438 \u043a\u0430\u043a\u0438\u0445 \u043e\u0431\u0441\u0442\u043e\u044f\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430\u0445.")
B.ai2=new A.t("\u041c\u0435\u0434\u0438\u043d\u0430","\u0423\u0440\u043e\u043a \u043b\u0443\u0447\u043d\u0438\u043a\u043e\u0432","\u0421\u043d\u0430\u0447\u0430\u043b\u0430 \u043c\u0443\u0441\u0443\u043b\u044c\u043c\u0430\u043d\u0435 \u043f\u043e\u0431\u0435\u0436\u0434\u0430\u043b\u0438. \u0423\u0432\u0438\u0434\u0435\u0432 \u043e\u0442\u0441\u0442\u0443\u043f\u043b\u0435\u043d\u0438\u0435 \u0432\u0440\u0430\u0433\u0430, \u0431\u043e\u043b\u044c\u0448\u0438\u043d\u0441\u0442\u0432\u043e \u043b\u0443\u0447\u043d\u0438\u043a\u043e\u0432 \u043f\u043e\u043a\u0438\u043d\u0443\u043b\u0438 \u0433\u043e\u0440\u0443 \u0440\u0430\u0434\u0438 \u0442\u0440\u043e\u0444\u0435\u0435\u0432. \u041a\u043e\u043d\u043d\u0438\u0446\u0430 \u0425\u0430\u043b\u0438\u0434\u0430 \u0438\u0431\u043d \u0430\u043b\u044c-\u0412\u0430\u043b\u0438\u0434\u0430 (\u0442\u043e\u0433\u0434\u0430 \u0435\u0449\u0451 \u043d\u0435 \u043c\u0443\u0441\u0443\u043b\u044c\u043c\u0430\u043d\u0438\u043d\u0430) \u0443\u0434\u0430\u0440\u0438\u043b\u0430 \u0432 \u0442\u044b\u043b. \u041f\u0440\u043e\u0440\u043e\u043a \ufdfa \u0431\u044b\u043b \u0440\u0430\u043d\u0435\u043d. \u042d\u0442\u043e\u0442 \u0443\u0440\u043e\u043a \u0443\u0447\u0438\u0442 \u043f\u043e\u0441\u043b\u0443\u0448\u0430\u043d\u0438\u044e.")
B.aiR=new A.t("\u041c\u0435\u0434\u0438\u043d\u0430","\u0428\u0430\u0445\u0438\u0434 \u0425\u0430\u043c\u0437\u0430","\u041f\u0440\u0438 \u0423\u0445\u0443\u0434\u0435 \u043f\u0430\u043b \u0425\u0430\u043c\u0437\u0430 \u2014 \u0434\u044f\u0434\u044f \u041f\u0440\u043e\u0440\u043e\u043a\u0430 \ufdfa, \xab\u043b\u0435\u0432 \u0410\u043b\u043b\u0430\u0445\u0430\xbb. \u041f\u0440\u043e\u0440\u043e\u043a \ufdfa \u043e\u0447\u0435\u043d\u044c \u0433\u043e\u0440\u0435\u0432\u0430\u043b \u043e \u043d\u0451\u043c \u0438 \u043d\u0430\u0437\u0432\u0430\u043b \u0435\u0433\u043e \u0433\u043e\u0441\u043f\u043e\u0434\u0438\u043d\u043e\u043c \u0448\u0430\u0445\u0438\u0434\u043e\u0432.")
B.akI=new A.t("\u041c\u0435\u0434\u0438\u043d\u0430","\u0411\u0438\u0442\u0432\u0430 \u0443 \u0440\u0432\u0430","\u0412 \u043f\u044f\u0442\u044b\u0439 \u0433\u043e\u0434 \u0445\u0438\u0434\u0436\u0440\u044b \u043f\u0440\u043e\u0442\u0438\u0432 \u041c\u0435\u0434\u0438\u043d\u044b \u0441\u043e\u0431\u0440\u0430\u043b\u043e\u0441\u044c \u0432\u043e\u0439\u0441\u043a\u043e \u0441\u043e\u044e\u0437\u043d\u044b\u0445 \u043f\u043b\u0435\u043c\u0451\u043d \u2014 \u043e\u043a\u043e\u043b\u043e \u0434\u0435\u0441\u044f\u0442\u0438 \u0442\u044b\u0441\u044f\u0447. \u041f\u043e \u0441\u043e\u0432\u0435\u0442\u0443 \u0421\u0430\u043b\u044c\u043c\u0430\u043d\u0430 \u0430\u043b\u044c-\u0424\u0430\u0440\u0438\u0441\u0438 \u0432\u043e\u043a\u0440\u0443\u0433 \u0433\u043e\u0440\u043e\u0434\u0430 \u0432\u044b\u0440\u044b\u043b\u0438 \u0440\u043e\u0432. \u041f\u0440\u043e\u0440\u043e\u043a \ufdfa \u0441\u0430\u043c \u043a\u043e\u043f\u0430\u043b \u0432\u043c\u0435\u0441\u0442\u0435 \u0441\u043e \u0432\u0441\u0435\u043c\u0438, \u0442\u0435\u0440\u043f\u044f \u0433\u043e\u043b\u043e\u0434.")
B.alK=new A.t("\u041c\u0435\u0434\u0438\u043d\u0430","\u0412\u0435\u0442\u0435\u0440 \u0438 \u0445\u043e\u043b\u043e\u0434","\u041e\u0441\u0430\u0434\u0430 \u0434\u043b\u0438\u043b\u0430\u0441\u044c \u0434\u043e\u043b\u0433\u043e. \u0410\u043b\u043b\u0430\u0445 \u043f\u043e\u0441\u043b\u0430\u043b \u0441\u0438\u043b\u044c\u043d\u044b\u0439 \u0445\u043e\u043b\u043e\u0434\u043d\u044b\u0439 \u0432\u0435\u0442\u0435\u0440, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u043e\u043f\u0440\u043e\u043a\u0438\u0434\u044b\u0432\u0430\u043b \u043a\u043e\u0442\u043b\u044b \u0438 \u0433\u0430\u0441\u0438\u043b \u043a\u043e\u0441\u0442\u0440\u044b \u0432\u0440\u0430\u0433\u043e\u0432 (33:9). \u0421\u043e\u044e\u0437\u043d\u0438\u043a\u0438 \u0440\u0430\u0437\u043e\u0448\u043b\u0438\u0441\u044c \u043d\u0438 \u0441 \u0447\u0435\u043c.")
B.ak0=new A.t("\u041c\u0435\u0434\u0438\u043d\u0430","\u0425\u0443\u0434\u0430\u0439\u0431\u0438\u044f","\u0412 \u0448\u0435\u0441\u0442\u043e\u0439 \u0433\u043e\u0434 \u0445\u0438\u0434\u0436\u0440\u044b \u041f\u0440\u043e\u0440\u043e\u043a \ufdfa \u0441 1400 \u0441\u043f\u043e\u0434\u0432\u0438\u0436\u043d\u0438\u043a\u0430\u043c\u0438 \u043e\u0442\u043f\u0440\u0430\u0432\u0438\u043b\u0441\u044f \u0432 \u041c\u0435\u043a\u043a\u0443 \u0441\u043e\u0432\u0435\u0440\u0448\u0438\u0442\u044c \u0443\u043c\u0440\u0443, \u0431\u0435\u0437 \u043e\u0440\u0443\u0436\u0438\u044f \u0434\u043b\u044f \u0432\u043e\u0439\u043d\u044b. \u041a\u0443\u0440\u0430\u0439\u0448\u0438\u0442\u044b \u043d\u0435 \u043f\u0443\u0441\u0442\u0438\u043b\u0438 \u0438\u0445. \u0422\u043e\u0433\u0434\u0430 \u0441\u043f\u043e\u0434\u0432\u0438\u0436\u043d\u0438\u043a\u0438 \u0434\u0430\u043b\u0438 \u043a\u043b\u044f\u0442\u0432\u0443 \u043f\u043e\u0434 \u0434\u0435\u0440\u0435\u0432\u043e\u043c \u2014 \u0431\u0430\u0439\u0430\u0442 \u0430\u0440-\u0420\u0438\u0434\u0432\u0430\u043d, \u043a\u043e\u0442\u043e\u0440\u0443\u044e \u0410\u043b\u043b\u0430\u0445 \u043f\u043e\u0445\u0432\u0430\u043b\u0438\u043b \u0432 \u041a\u043e\u0440\u0430\u043d\u0435 (48:18).")
B.alx=new A.t("\u041c\u0435\u0434\u0438\u043d\u0430","\u042f\u0432\u043d\u0430\u044f \u043f\u043e\u0431\u0435\u0434\u0430","\u0412 \u0425\u0443\u0434\u0430\u0439\u0431\u0438\u0438 \u0431\u044b\u043b \u0437\u0430\u043a\u043b\u044e\u0447\u0451\u043d \u043c\u0438\u0440 \u043d\u0430 \u0434\u0435\u0441\u044f\u0442\u044c \u043b\u0435\u0442. \u0423\u0441\u043b\u043e\u0432\u0438\u044f \u043a\u0430\u0437\u0430\u043b\u0438\u0441\u044c \u0442\u044f\u0436\u0451\u043b\u044b\u043c\u0438, \u043d\u043e \u041a\u043e\u0440\u0430\u043d \u043d\u0430\u0437\u0432\u0430\u043b \u044d\u0442\u043e\u0442 \u0434\u043e\u0433\u043e\u0432\u043e\u0440 \u044f\u0432\u043d\u043e\u0439 \u043f\u043e\u0431\u0435\u0434\u043e\u0439 (48:1): \u0432 \u0433\u043e\u0434\u044b \u043c\u0438\u0440\u0430 \u0438\u0441\u043b\u0430\u043c \u0440\u0430\u0441\u043f\u0440\u043e\u0441\u0442\u0440\u0430\u043d\u0438\u043b\u0441\u044f \u0431\u044b\u0441\u0442\u0440\u0435\u0435, \u0447\u0435\u043c \u043f\u0440\u0435\u0436\u0434\u0435.")
