B.akV=new A.t("\u041a\u043e\u043d\u0447\u0438\u043d\u0430","\u041a\u043e\u043d\u0447\u0438\u043d\u0430 \u041f\u0440\u043e\u0440\u043e\u043a\u0430 \ufdfa","\u041f\u0440\u043e\u0440\u043e\u043a \ufdfa \u0441\u043a\u043e\u043d\u0447\u0430\u043b\u0441\u044f \u0432 \u043f\u043e\u043d\u0435\u0434\u0435\u043b\u044c\u043d\u0438\u043a \u043c\u0435\u0441\u044f\u0446\u0430 \u0440\u0430\u0431\u0438 \u0430\u043b\u044c-\u0430\u0432\u0432\u0430\u043b\u044c 11 \u0433\u043e\u0434\u0430 \u0445\u0438\u0434\u0436\u0440\u044b (632 \u0433.) \u0432 \u0432\u043e\u0437\u0440\u0430\u0441\u0442\u0435 63 \u043b\u0435\u0442. \u0415\u0433\u043e \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0435 \u0441\u043b\u043e\u0432\u0430 \u0431\u044b\u043b\u0438: \xab\u0421 \u0412\u044b\u0441\u0448\u0438\u043c \u0414\u0440\u0443\u0433\u043e\u043c\xbb (\u0411\u0443\u0445\u0430\u0440\u0438).")
B.amf=new A.t("\u041a\u043e\u043d\u0447\u0438\u043d\u0430","\u0421\u043b\u043e\u0432\u0430 \u0410\u0431\u0443 \u0411\u0430\u043a\u0440\u0430","\u0421\u043f\u043e\u0434\u0432\u0438\u0436\u043d\u0438\u043a\u0438 \u043d\u0435 \u043c\u043e\u0433\u043b\u0438 \u043f\u043e\u0432\u0435\u0440\u0438\u0442\u044c \u0432 \u0441\u043b\u0443\u0447\u0438\u0432\u0448\u0435\u0435\u0441\u044f. \u0410\u0431\u0443 \u0411\u0430\u043a\u0440 \u0432\u044b\u0448\u0435\u043b \u043a \u043b\u044e\u0434\u044f\u043c \u0438 \u0441\u043a\u0430\u0437\u0430\u043b: \xab\u041a\u0442\u043e \u043f\u043e\u043a\u043b\u043e\u043d\u044f\u043b\u0441\u044f \u041c\u0443\u0445\u0430\u043c\u043c\u0430\u0434\u0443 \u2014 \u041c\u0443\u0445\u0430\u043c\u043c\u0430\u0434 \u0443\u043c\u0435\u0440. \u0410 \u043a\u0442\u043e \u043f\u043e\u043a\u043b\u043e\u043d\u044f\u043b\u0441\u044f \u0410\u043b\u043b\u0430\u0445\u0443 \u2014 \u0410\u043b\u043b\u0430\u0445 \u0436\u0438\u0432 \u0438 \u043d\u0435 \u0443\u043c\u0438\u0440\u0430\u0435\u0442\xbb \u2014 \u0438 \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u043b \u0430\u044f\u0442 3:144.")
